"""Build ``golden.json`` for the ``document`` kind from ``procedure_fixture.pdf``.

Run it from PowerShell on this repo's venv interpreter, never a bare python:

    & .\\.venv\\Scripts\\python.exe tests\\fixtures\\document\\make_golden.py

It imports ``doc_tools``, which pulls the Dagster defs and so ``python-magic``;
under the Bash tool that import never returns (see CLAUDE.md).

WHAT IS PINNED AND WHAT IS NOT
------------------------------
Everything here is deterministic, which is unusual for a golden in this repo and
is the point of the ``document`` kind: the outline is read off the page by
``document.document_outline`` with no model call, so the same bytes give the same
sections, the same page spans and the same ids on every run. There is no
``nondeterministic`` block of the kind ``tests/fixtures/*/golden.json`` carries
for LLM-derived fields, because nothing on this path is LLM-derived.

``fixture.pdf_sha256`` pins the INPUT. Re-running ``make_procedure.py`` produces
byte-identical output, so a change to that sha means the fixture's CONTENT
changed, which is a contract change and not a re-pin.
"""
from __future__ import annotations

import hashlib
import io
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", "..", ".."))
if ROOT not in sys.path:
    sys.path.insert(0, ROOT)

PDF = os.path.join(HERE, "procedure_fixture.pdf")
GOLDEN = os.path.join(HERE, "golden.json")

DOC_ID = "TP-204"


def pages_from_pdf(path: str) -> list[str]:
    import pdfplumber

    with pdfplumber.open(path) as pdf:
        return [(page.extract_text() or "") for page in pdf.pages]


def build() -> dict:
    from doc_tools.passes.dispatch import PassContext, run_passes_for_kind
    from doc_tools.utils.content_kind import KIND_MAPPING

    with io.open(PDF, "rb") as fh:
        pdf_bytes = fh.read()
    pages = pages_from_pdf(PDF)

    # Through the DISPATCHER, not by direct call: the golden then records what
    # the registry row actually runs, so a row edited to declare a different
    # pass tuple moves this file.
    ctx = PassContext(pages=tuple(pages), text="\n".join(pages), doc_id=DOC_ID)
    results = run_passes_for_kind("document", ctx)

    outline = None
    identity = None
    for result in results:
        if result.status != "ok":
            continue
        if result.name.endswith("document_outline"):
            outline = result.value
        elif result.name.endswith("document_identity"):
            identity = result.value

    row = KIND_MAPPING["document"]
    return {
        "_comment": (
            "GENERATED by tests/fixtures/document/make_golden.py. The pinned "
            "outline of procedure_fixture.pdf, read deterministically by the "
            "passes the `document` row declares. Nothing here is model-derived."
        ),
        "fixture": {
            "pdf": "procedure_fixture.pdf",
            "pdf_sha256": hashlib.sha256(pdf_bytes).hexdigest(),
            "pages": len(pages),
            "doc_id": DOC_ID,
        },
        "row": {
            "kind": row.kind,
            "domain_type": row.domain_type,
            "passes": list(row.passes),
            "outputs": list(row.outputs),
            "ingress_prefix": row.ingress_prefix,
            "file_suffixes": list(row.file_suffixes or ()),
        },
        "pass_results": [
            {"name": r.name, "status": r.status} for r in results
        ],
        # Pinned so a regression to "all four refused" fails here. The arm is
        # label-driven: contract_number is refused because a procedure has no
        # contract, which is a refusal recorded AS one and not a gap.
        "identity": identity.as_dict() if identity is not None else None,
        "outline": outline.as_dict() if outline is not None else None,
        "page_citations": [
            {
                "page": n,
                "section_id": outline.section_for_page(n).id,
                "heading": outline.section_for_page(n).heading,
            }
            for n in range(1, len(pages) + 1)
        ] if outline is not None else [],
    }


def main() -> int:
    golden = build()
    text = json.dumps(golden, indent=2, sort_keys=False) + "\n"
    if "--check" in sys.argv:
        current = ""
        if os.path.exists(GOLDEN):
            with io.open(GOLDEN, encoding="utf-8") as fh:
                current = fh.read()
        if current != text:
            print("GOLDEN DRIFT: regenerate with make_golden.py")
            return 1
        print("golden matches")
        return 0
    with io.open(GOLDEN, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(text)
    print("wrote", GOLDEN)
    print("sections:", len(golden["outline"]["sections"]) if golden["outline"] else 0)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
